/**
 * test-xml-editor.js — Integration test for vboxXmlEditor.js
 *
 * This script creates a sample .vbox XML file, applies various settings
 * via the XML editor, and verifies the results.
 *
 * Run: node test-xml-editor.js
 */

const fs = require('fs');
const path = require('path');
const vboxXmlEditor = require('./adapters/vboxXmlEditor');

// Sample .vbox XML content (based on real VirtualBox 7.x output)
const SAMPLE_VBOX_XML = `<?xml version="1.0"?>
<!--
** DO NOT EDIT THIS FILE.
** If you make changes to this file while any VirtualBox related application
** is running, your changes will be overwritten later, without taking effect.
** Use VBoxManage or the VirtualBox Manager GUI to make changes.
-->
<VirtualBox xmlns="http://www.virtualbox.org/" version="1.19-linux">
  <Machine uuid="{12345678-1234-1234-1234-123456789abc}" name="TestVM" OSType="Ubuntu_64" snapshotFolder="Snapshots" lastStateChange="2026-05-30T12:00:00Z">
    <MediaRegistry>
      <HardDisks>
        <HardDisk uuid="{abcdefab-cdef-abcd-efab-cdefabcdefab}" location="TestVM.vdi" format="VDI" type="Normal"/>
      </HardDisks>
    </MediaRegistry>
    <ExtraData>
      <ExtraDataItem name="GUI/LastGuestSizeHint" value="1920,1080"/>
      <ExtraDataItem name="VMXposed/GuestDisplayFullscreen" value="on"/>
    </ExtraData>
    <Hardware>
      <CPU count="2">
        <PAE enabled="true"/>
        <LongMode enabled="true"/>
        <HardwareVirtExLargePages enabled="true"/>
      </CPU>
      <Memory RAMSize="4096"/>
      <Display VRAMSize="64" monitorCount="1" accelerate3D="false">
        <GraphicsAdapter type="VMSVGA"/>
      </Display>
      <BIOS>
        <IOAPIC enabled="true"/>
        <Boot>
          <Order position="1" device="HardDisk"/>
          <Order position="2" device="DVD"/>
          <Order position="3" device="None"/>
          <Order position="4" device="None"/>
        </Boot>
      </BIOS>
      <USB>
        <Controllers>
          <Controller name="OHCI" type="OHCI"/>
        </Controllers>
      </USB>
      <Network>
        <Adapter slot="0" enabled="true" MACAddress="080027ABCDEF" type="82540EM">
          <NAT/>
        </Adapter>
      </Network>
      <AudioAdapter controller="HDA" enabled="true"/>
      <Clipboard mode="Bidirectional"/>
      <DragAndDrop mode="Disabled"/>
      <SharedFolders>
        <SharedFolder name="shared" hostPath="C:\\Users\\Test\\Documents" writable="true" autoMount="true"/>
      </SharedFolders>
    </Hardware>
  </Machine>
</VirtualBox>`;

let passed = 0;
let failed = 0;

function assert(condition, message) {
  if (condition) {
    console.log(`  ✓ ${message}`);
    passed++;
  } else {
    console.error(`  ✗ FAIL: ${message}`);
    failed++;
  }
}

function assertStrictEqual(actual, expected, message) {
  if (actual === expected) {
    console.log(`  ✓ ${message}`);
    passed++;
  } else {
    console.error(`  ✗ FAIL: ${message}`);
    console.error(`    Expected: ${JSON.stringify(expected)}`);
    console.error(`    Actual:   ${JSON.stringify(actual)}`);
    failed++;
  }
}

// ── Test 1: Read Settings ──────────────────────────────────────────
console.log('\n═══ Test 1: Read Settings from XML ═══');
const settings = vboxXmlEditor.readCurrentSettings(SAMPLE_VBOX_XML);

assertStrictEqual(settings.ram, 4096, 'RAM should be 4096 MB');
assertStrictEqual(settings.cpus, 2, 'CPU count should be 2');
assertStrictEqual(settings.vram, 64, 'VRAM should be 64 MB');
assertStrictEqual(settings.monitorCount, 1, 'Monitor count should be 1');
assertStrictEqual(settings.accelerate3d, false, '3D acceleration should be off');
assertStrictEqual(settings.graphicsController, 'VMSVGA', 'Graphics controller should be VMSVGA');
assertStrictEqual(settings.clipboardMode, 'bidirectional', 'Clipboard should be bidirectional');
assertStrictEqual(settings.dragAndDrop, 'disabled', 'Drag & drop should be disabled');
assertStrictEqual(settings.audioEnabled, true, 'Audio should be enabled');
assertStrictEqual(settings.audioController, 'hda', 'Audio controller should be HDA');
assertStrictEqual(settings.usbEnabled, true, 'USB should be enabled');
assert(Array.isArray(settings.bootOrder), 'Boot order should be an array');
assertStrictEqual(settings.bootOrder[0], 'disk', 'First boot device should be disk');
assertStrictEqual(settings.bootOrder[1], 'dvd', 'Second boot device should be dvd');
assert(settings.networkMode === 'nat', 'Network mode should be NAT');
assert(Array.isArray(settings.sharedFolders), 'Shared folders should be an array');
assertStrictEqual(settings.sharedFolders.length, 1, 'Should have 1 shared folder');
assertStrictEqual(settings.sharedFolders[0].name, 'shared', 'Shared folder name should be "shared"');

// ── Test 2: Modify Memory ──────────────────────────────────────────
console.log('\n═══ Test 2: Modify Memory ═══');
const xmlWithNewRam = vboxXmlEditor.setMemory(SAMPLE_VBOX_XML, 8192);
const ramSettings = vboxXmlEditor.readCurrentSettings(xmlWithNewRam);
assertStrictEqual(ramSettings.ram, 8192, 'RAM should now be 8192 MB');
// Other settings should be unchanged
assertStrictEqual(ramSettings.cpus, 2, 'CPU count should still be 2');
assertStrictEqual(ramSettings.vram, 64, 'VRAM should still be 64 MB');

// ── Test 3: Modify CPU ─────────────────────────────────────────────
console.log('\n═══ Test 3: Modify CPU ═══');
const xmlWithNewCpu = vboxXmlEditor.setCPU(SAMPLE_VBOX_XML, 8);
const cpuSettings = vboxXmlEditor.readCurrentSettings(xmlWithNewCpu);
assertStrictEqual(cpuSettings.cpus, 8, 'CPU count should now be 8');
assertStrictEqual(cpuSettings.ram, 4096, 'RAM should still be 4096 MB');

// ── Test 4: Modify Display ─────────────────────────────────────────
console.log('\n═══ Test 4: Modify Display (VRAM + 3D) ═══');
const xmlWithNewDisplay = vboxXmlEditor.setDisplay(SAMPLE_VBOX_XML, { vram: 256, accelerate3D: true });
const displaySettings = vboxXmlEditor.readCurrentSettings(xmlWithNewDisplay);
assertStrictEqual(displaySettings.vram, 256, 'VRAM should now be 256 MB');
assertStrictEqual(displaySettings.accelerate3d, true, '3D acceleration should now be on');

// ── Test 5: Modify Graphics Controller ─────────────────────────────
console.log('\n═══ Test 5: Modify Graphics Controller ═══');
const xmlWithNewGfx = vboxXmlEditor.setGraphicsController(SAMPLE_VBOX_XML, 'VBoxSVGA');
const gfxSettings = vboxXmlEditor.readCurrentSettings(xmlWithNewGfx);
assertStrictEqual(gfxSettings.graphicsController, 'VBoxSVGA', 'Graphics controller should now be VBoxSVGA');

// ── Test 6: Modify Clipboard ───────────────────────────────────────
console.log('\n═══ Test 6: Modify Clipboard ═══');
const xmlWithNewClip = vboxXmlEditor.setClipboard(SAMPLE_VBOX_XML, 'hosttoguest');
const clipSettings = vboxXmlEditor.readCurrentSettings(xmlWithNewClip);
assertStrictEqual(clipSettings.clipboardMode, 'hosttoguest', 'Clipboard should now be hosttoguest');

// ── Test 7: Modify Drag & Drop ────────────────────────────────────
console.log('\n═══ Test 7: Modify Drag & Drop ═══');
const xmlWithNewDnD = vboxXmlEditor.setDragAndDrop(SAMPLE_VBOX_XML, 'bidirectional');
const dndSettings = vboxXmlEditor.readCurrentSettings(xmlWithNewDnD);
assertStrictEqual(dndSettings.dragAndDrop, 'bidirectional', 'Drag & drop should now be bidirectional');

// ── Test 8: Modify Boot Order ─────────────────────────────────────
console.log('\n═══ Test 8: Modify Boot Order ═══');
const xmlWithNewBoot = vboxXmlEditor.setBootOrder(SAMPLE_VBOX_XML, ['dvd', 'disk', 'none', 'none']);
const bootSettings = vboxXmlEditor.readCurrentSettings(xmlWithNewBoot);
assertStrictEqual(bootSettings.bootOrder[0], 'dvd', 'First boot device should now be dvd');
assertStrictEqual(bootSettings.bootOrder[1], 'disk', 'Second boot device should now be disk');

// ── Test 9: Modify Audio ──────────────────────────────────────────
console.log('\n═══ Test 9: Modify Audio ═══');
const xmlAudioOff = vboxXmlEditor.setAudio(SAMPLE_VBOX_XML, { enabled: false });
const audioOffSettings = vboxXmlEditor.readCurrentSettings(xmlAudioOff);
assertStrictEqual(audioOffSettings.audioEnabled, false, 'Audio should now be disabled');

// ── Test 10: Modify USB ───────────────────────────────────────────
console.log('\n═══ Test 10: Modify USB ═══');
const xmlUsbOff = vboxXmlEditor.setUSB(SAMPLE_VBOX_XML, false);
const usbOffSettings = vboxXmlEditor.readCurrentSettings(xmlUsbOff);
assertStrictEqual(usbOffSettings.usbEnabled, false, 'USB should now be disabled');

// ── Test 11: Set ExtraData ────────────────────────────────────────
console.log('\n═══ Test 11: Set ExtraData ═══');
const xmlWithExtra = vboxXmlEditor.setExtraData(SAMPLE_VBOX_XML, 'VMXposed/TestKey', 'TestValue');
const extraSettings = vboxXmlEditor.readCurrentSettings(xmlWithExtra);
assertStrictEqual(extraSettings.extraData['VMXposed/TestKey'], 'TestValue', 'ExtraData should have new key');
// Existing ExtraData should be preserved
assertStrictEqual(extraSettings.extraData['VMXposed/GuestDisplayFullscreen'], 'on', 'Existing ExtraData should be preserved');

// ── Test 12: Update Existing ExtraData ────────────────────────────
console.log('\n═══ Test 12: Update Existing ExtraData ═══');
const xmlUpdatedExtra = vboxXmlEditor.setExtraData(SAMPLE_VBOX_XML, 'VMXposed/GuestDisplayFullscreen', 'off');
const updatedExtraSettings = vboxXmlEditor.readCurrentSettings(xmlUpdatedExtra);
assertStrictEqual(updatedExtraSettings.extraData['VMXposed/GuestDisplayFullscreen'], 'off', 'ExtraData should be updated to "off"');

// ── Test 13: Modify Shared Folders ────────────────────────────────
console.log('\n═══ Test 13: Modify Shared Folders ═══');
const newFolders = [
  { name: 'docs', hostPath: 'C:\\Users\\Test\\Documents', autoMount: true },
  { name: 'downloads', hostPath: 'C:\\Users\\Test\\Downloads', autoMount: false }
];
const xmlWithNewFolders = vboxXmlEditor.setSharedFolders(SAMPLE_VBOX_XML, newFolders);
const folderSettings = vboxXmlEditor.readCurrentSettings(xmlWithNewFolders);
assertStrictEqual(folderSettings.sharedFolders.length, 2, 'Should now have 2 shared folders');
assertStrictEqual(folderSettings.sharedFolders[0].name, 'docs', 'First folder should be "docs"');
assertStrictEqual(folderSettings.sharedFolders[1].name, 'downloads', 'Second folder should be "downloads"');

// ── Test 14: Chain Multiple Modifications ─────────────────────────
console.log('\n═══ Test 14: Chain Multiple Modifications ═══');
let chainedXml = SAMPLE_VBOX_XML;
chainedXml = vboxXmlEditor.setMemory(chainedXml, 16384);
chainedXml = vboxXmlEditor.setCPU(chainedXml, 4);
chainedXml = vboxXmlEditor.setDisplay(chainedXml, { vram: 128, accelerate3D: true });
chainedXml = vboxXmlEditor.setClipboard(chainedXml, 'bidirectional');
chainedXml = vboxXmlEditor.setDragAndDrop(chainedXml, 'bidirectional');
chainedXml = vboxXmlEditor.setBootOrder(chainedXml, ['disk', 'dvd', 'none', 'none']);
const chainedSettings = vboxXmlEditor.readCurrentSettings(chainedXml);
assertStrictEqual(chainedSettings.ram, 16384, 'Chained RAM should be 16384 MB');
assertStrictEqual(chainedSettings.cpus, 4, 'Chained CPU count should be 4');
assertStrictEqual(chainedSettings.vram, 128, 'Chained VRAM should be 128 MB');
assertStrictEqual(chainedSettings.accelerate3d, true, 'Chained 3D should be on');
assertStrictEqual(chainedSettings.clipboardMode, 'bidirectional', 'Chained clipboard should be bidirectional');
assertStrictEqual(chainedSettings.dragAndDrop, 'bidirectional', 'Chained drag & drop should be bidirectional');

// ── Test 15: File I/O (Write and Read) ────────────────────────────
console.log('\n═══ Test 15: File I/O (Write and Read) ═══');
const tmpDir = path.join(__dirname, '.test-tmp');
if (!fs.existsSync(tmpDir)) fs.mkdirSync(tmpDir, { recursive: true });
const tmpFile = path.join(tmpDir, 'test-vm.vbox');
try {
  vboxXmlEditor.writeVboxXml(tmpFile, chainedXml);
  assert(fs.existsSync(tmpFile), 'Written .vbox file should exist');
  const readBack = vboxXmlEditor.readVboxXml(tmpFile);
  const readBackSettings = vboxXmlEditor.readCurrentSettings(readBack);
  assertStrictEqual(readBackSettings.ram, 16384, 'Read-back RAM should be 16384 MB');
  assertStrictEqual(readBackSettings.cpus, 4, 'Read-back CPU count should be 4');

  // Test backup
  const backupPath = vboxXmlEditor.backupVboxFile(tmpFile);
  assert(fs.existsSync(backupPath), 'Backup file should exist');
  fs.unlinkSync(backupPath);
} finally {
  if (fs.existsSync(tmpFile)) fs.unlinkSync(tmpFile);
  if (fs.existsSync(tmpDir)) fs.rmdirSync(tmpDir);
}

// ── Test 16: Safety Checks ────────────────────────────────────────
console.log('\n═══ Test 16: Safety Checks ═══');
const safeResult = vboxXmlEditor.ensureSafeForXmlEdit('/nonexistent/path.vbox', 'poweroff');
assertStrictEqual(safeResult.safe, false, 'Should not be safe for nonexistent file');

const runningResult = vboxXmlEditor.ensureSafeForXmlEdit('/some/path.vbox', 'running');
assertStrictEqual(runningResult.safe, false, 'Should not be safe for running VM');

// ── Test 17: VBoxSVC Detection ────────────────────────────────────
console.log('\n═══ Test 17: VBoxSVC Detection ═══');
const svcStatus = vboxXmlEditor.isVBoxSVCActive();
assert(typeof svcStatus.active === 'boolean', 'VBoxSVC active should be boolean');
assert(Array.isArray(svcStatus.pids), 'VBoxSVC pids should be array');
assert(typeof svcStatus.details === 'string', 'VBoxSVC details should be string');
console.log(`  ℹ VBoxSVC status: ${svcStatus.details}`);

// ── Test 18: applySettingsToXml ───────────────────────────────────
console.log('\n═══ Test 18: applySettingsToXml (orchestrator) ═══');
const tmpDir2 = path.join(__dirname, '.test-tmp');
if (!fs.existsSync(tmpDir2)) fs.mkdirSync(tmpDir2, { recursive: true });
const tmpFile2 = path.join(tmpDir2, 'test-vm-apply.vbox');
try {
  fs.writeFileSync(tmpFile2, SAMPLE_VBOX_XML, 'utf8');
  const applyResult = vboxXmlEditor.applySettingsToXml(tmpFile2, {
    ram: 32768,
    cpus: 16,
    vram: 256,
    clipboardMode: 'bidirectional',
    dragAndDrop: 'bidirectional',
    audioEnabled: false,
    bootOrder: ['dvd', 'disk', 'none', 'none']
  });
  assert(applyResult.success, 'applySettingsToXml should succeed');
  assert(applyResult.applied.length > 0, 'Should have applied settings');
  assert(applyResult.backupPath.length > 0, 'Should have created backup');

  const finalXml = vboxXmlEditor.readVboxXml(tmpFile2);
  const finalSettings = vboxXmlEditor.readCurrentSettings(finalXml);
  assertStrictEqual(finalSettings.ram, 32768, 'Final RAM should be 32768 MB');
  assertStrictEqual(finalSettings.cpus, 16, 'Final CPU count should be 16');
  assertStrictEqual(finalSettings.vram, 256, 'Final VRAM should be 256 MB');
  assertStrictEqual(finalSettings.clipboardMode, 'bidirectional', 'Final clipboard should be bidirectional');
  assertStrictEqual(finalSettings.dragAndDrop, 'bidirectional', 'Final drag & drop should be bidirectional');
  assertStrictEqual(finalSettings.audioEnabled, false, 'Final audio should be disabled');
  assertStrictEqual(finalSettings.bootOrder[0], 'dvd', 'Final boot order first should be dvd');

  // Cleanup backup
  if (fs.existsSync(applyResult.backupPath)) fs.unlinkSync(applyResult.backupPath);
} finally {
  if (fs.existsSync(tmpFile2)) fs.unlinkSync(tmpFile2);
  if (fs.existsSync(tmpDir2)) fs.rmdirSync(tmpDir2);
}

// ── Summary ───────────────────────────────────────────────────────
console.log('\n═══════════════════════════════════════════════');
console.log(`  Results: ${passed} passed, ${failed} failed`);
console.log('═══════════════════════════════════════════════');

if (failed > 0) {
  process.exit(1);
}
